import { HalfFloatType, Matrix4, NearestFilter, NoColorSpace, Quaternion, Vector2, Vector3, WebGLRenderTarget, type PerspectiveCamera, type Texture, type WebGLRenderer } from 'three'
import { Pass } from 'postprocessing'
import { isTemporalDepthVolume, type DepthVolume, type TemporalDepthVolume } from './DepthVolume'
import { DepthVolumeTemporalMaterial } from './DepthVolumeTemporalMaterial'

export const DEFAULT_VOLUME_HISTORY_BYTES = 64 * 1024 * 1024

export function temporalWeight(volume: DepthVolume): number {
  return isTemporalDepthVolume(volume) && Number.isFinite(volume.temporalBlend) ? Math.max(0, Math.min(0.95, volume.temporalBlend)) : 0
}

/** Both color and local position use nearest fetches, with checked interpolation in GLSL. */
export function createVolumeTarget(width: number, height: number, count = 1): WebGLRenderTarget {
  const target = new WebGLRenderTarget(width, height, {
    count, type: HalfFloatType, depthBuffer: false, stencilBuffer: false,
    minFilter: NearestFilter, magFilter: NearestFilter
  })
  for (const texture of target.textures) {
    texture.colorSpace = NoColorSpace
    texture.generateMipmaps = false
  }
  return target
}

export interface TemporalFrame {
  readonly volume: TemporalDepthVolume
  readonly size: Vector2
  read: WebGLRenderTarget
  write: WebGLRenderTarget
  readonly previousClip: Matrix4
  readonly currentClip: Matrix4
  readonly projection: Matrix4
  readonly model: Matrix4
  readonly cameraLocal: Vector3
  readonly orientation: Quaternion
  camera: PerspectiveCamera | null
  revision: number
  samples: number
  phase: number
  jitter: number
  weight: number
}

class TemporalResolvePass extends Pass {
  public readonly material = new DepthVolumeTemporalMaterial()
  public constructor() { super('DepthVolume temporal'); this.fullscreenMaterial = this.material }
  public draw(renderer: WebGLRenderer, target: WebGLRenderTarget): void {
    renderer.setRenderTarget(target)
    renderer.render(this.scene, this.camera)
  }
}

/** Histories belong to a pass and a volume; no image can leak between volumes or cameras. */
export class DepthVolumeHistory {
  private readonly records = new Map<TemporalDepthVolume, TemporalFrame>()
  private bytes = 0
  private pass: TemporalResolvePass | null = null
  private readonly localCamera = new Vector3()
  private readonly orientation = new Quaternion()
  private readonly inverse = new Matrix4()

  public constructor(private readonly maxBytes = DEFAULT_VOLUME_HISTORY_BYTES) {}

  public prepare(volumes: readonly DepthVolume[], resolution: Vector2): void {
    const active = new Set(volumes.filter(volume => temporalWeight(volume) > 0))
    for (const [volume, frame] of this.records) {
      const scale = Math.max(0.25, Math.min(1, volume.resolutionScale))
      if (!active.has(volume) || frame.size.x !== Math.ceil(resolution.x * scale) || frame.size.y !== Math.ceil(resolution.y * scale)) this.forget(volume)
    }
  }

  public forget(volume: DepthVolume): void {
    if (!isTemporalDepthVolume(volume)) return
    const frame = this.records.get(volume)
    if (!frame) return
    frame.read.dispose()
    frame.write.dispose()
    this.bytes -= frame.size.x * frame.size.y * 32
    this.records.delete(volume)
  }

  public begin(volume: TemporalDepthVolume, camera: PerspectiveCamera, size: Vector2): TemporalFrame | null {
    let frame = this.records.get(volume)
    if (!frame) {
      const bytes = size.x * size.y * 32
      if (this.bytes + bytes > this.maxBytes) return null
      frame = {
        volume, size: size.clone(), read: createVolumeTarget(size.x, size.y, 2), write: createVolumeTarget(size.x, size.y, 2),
        previousClip: new Matrix4(), currentClip: new Matrix4(), projection: new Matrix4(), model: new Matrix4(),
        cameraLocal: new Vector3(), orientation: new Quaternion(), camera: null, revision: -1,
        samples: 0, phase: 0, jitter: 0, weight: 0
      }
      this.records.set(volume, frame)
      this.bytes += bytes
    }
    camera.updateWorldMatrix(true, false)
    volume.updateWorldMatrix(true, false)
    this.inverse.copy(volume.matrixWorld).invert()
    camera.getWorldPosition(this.localCamera).applyMatrix4(this.inverse)
    camera.getWorldQuaternion(this.orientation)
    if (frame.camera !== camera || frame.revision !== volume.temporalRevision ||
        !frame.projection.equals(camera.projectionMatrix) || !frame.model.equals(volume.matrixWorld) ||
        frame.cameraLocal.distanceToSquared(this.localCamera) > 0.25 || Math.abs(frame.orientation.dot(this.orientation)) < Math.cos(Math.PI / 24)) {
      this.invalidate(frame)
    }
    frame.camera = camera
    frame.revision = volume.temporalRevision
    frame.projection.copy(camera.projectionMatrix)
    frame.model.copy(volume.matrixWorld)
    frame.cameraLocal.copy(this.localCamera)
    frame.orientation.copy(this.orientation)
    // Cancel world translations on the CPU BEFORE multiplying by projection.
    frame.currentClip.multiplyMatrices(camera.matrixWorldInverse, volume.matrixWorld).premultiply(camera.projectionMatrix)
    frame.weight = Math.min(temporalWeight(volume), frame.samples / (frame.samples + 1))
    // 16 phases of a base-two low-discrepancy sequence, beginning with static phase0.
    const phase = frame.phase
    frame.jitter = ((phase & 1) * 8 + (phase & 2) * 2 + (phase & 4) / 2 + (phase & 8) / 8) / 16
    return frame
  }

  public resolve(renderer: WebGLRenderer, current: WebGLRenderTarget, frame: TemporalFrame): Texture {
    this.pass ??= new TemporalResolvePass()
    const material = this.pass.material, u = material.uniforms
    u.currentColor.value = current.textures[0]
    u.currentPosition.value = current.textures[1]
    u.historyColor.value = frame.read.textures[0]
    u.historyPosition.value = frame.read.textures[1]
    u.previousClip.value.copy(frame.previousClip)
    u.currentClip.value.copy(frame.currentClip)
    u.imageSize.value.copy(frame.size)
    u.historyWeight.value = frame.weight
    try { this.pass.draw(renderer, frame.write); return frame.write.texture }
    finally { material.unbind() }
  }

  public commit(frame: TemporalFrame): void {
    const old = frame.read
    frame.read = frame.write
    frame.write = old
    frame.previousClip.copy(frame.currentClip)
    frame.samples = Math.min(frame.samples + 1, 32)
    frame.phase = (frame.phase + 1) % 16
  }

  public invalidate(frame: TemporalFrame): void { frame.samples = 0; frame.phase = 0 }
  public clear(): void { for (const volume of this.records.keys()) this.forget(volume) }
  public dispose(): void { this.clear(); this.pass?.dispose(); this.pass = null }
}

import { BasicDepthPacking, type Object3D, type PerspectiveCamera, type Texture, type WebGLRenderer, type WebGLRenderTarget, Vector2, Vector3 } from 'three'
import { DepthCopyPass, Pass } from 'postprocessing'
import type { DepthVolumeRegistry } from '@/core/services/DepthVolumeRegistry'
import { DEPTH_VOLUME_LAYER, type DepthVolume } from '@/core/graphic/passes/DepthVolume'
import { DepthVolumeResolutionRenderer } from './DepthVolumeResolutionRenderer'

/** Тип упаковки глубины библиотека объявляет, но не экспортирует — берём из сигнатуры Pass */
type DepthPacking = Parameters<Pass['setDepthTexture']>[1]

/** Фильтр передних объёмов (LensFrontSorter подходит структурно) */
export interface FrontVolumeFilter {
  isFrontVolume(volume: DepthVolume): boolean
}

/**
 * Объёмы от дальнего к ближнему по дальней кромке: расстояние центра до камеры
 * + радиус описанной сферы (boundingRadius в мировом масштабе). Объёмы с общим
 * центром (кокон туманности и пояс вокруг одной звезды) так упорядочиваются по
 * охвату, а не по порядку регистрации — блендинг «поверх» зависит от порядка.
 */
export function orderFarToNear(volumes: readonly DepthVolume[], camera: Object3D): DepthVolume[] {
  const cameraWorld = camera.getWorldPosition(new Vector3())
  const position = new Vector3()
  const scale = new Vector3()
  const farExtent = new Map<DepthVolume, number>()
  for (const volume of volumes) {
    volume.getWorldPosition(position)
    volume.getWorldScale(scale)
    const worldRadius = (volume.boundingRadius ?? 0) * Math.max(scale.x, scale.y, scale.z)
    farExtent.set(volume, position.distanceTo(cameraWorld) + worldRadius)
  }
  return [...volumes].sort((a, b) => farExtent.get(b)! - farExtent.get(a)!)
}

/**
 * Объёмы в target камерой на DEPTH_VOLUME_LAYER: каждому на время рендера
 * привязана копия глубины сцены. Маска камеры и автообновление теней
 * возвращаются
 */
export function drawDepthVolumes(
  renderer: WebGLRenderer,
  target: WebGLRenderTarget | null,
  camera: PerspectiveCamera,
  volumes: readonly DepthVolume[],
  sceneDepth: Texture,
  resolution: Vector2,
  scaled?: DepthVolumeResolutionRenderer
): void {
  const mask = camera.layers.mask
  const shadowMapAutoUpdate = renderer.shadowMap.autoUpdate
  const logFarFactor = Math.log2(camera.far + 1)

  try {
    camera.layers.set(DEPTH_VOLUME_LAYER)
    renderer.shadowMap.autoUpdate = false
    renderer.setRenderTarget(target)
    scaled?.prepare(volumes, resolution)

    for (const volume of volumes) {
      try {
        volume.bindSceneDepth(sceneDepth, resolution, logFarFactor)
        if (scaled) scaled.render(renderer, target, camera, volume, sceneDepth, resolution, logFarFactor)
        else renderer.render(volume, camera)
      } finally {
        volume.unbindSceneDepth()
      }
    }
  } finally {
    camera.layers.mask = mask
    renderer.shadowMap.autoUpdate = shadowMapAutoUpdate
  }
}

/**
 * DepthVolumePass — объёмные эффекты (пыль колец, туманности) поверх
 * отрендеренной сцены с обрывом марша по её глубине.
 *
 * Зачем отдельный пасс. Объём — реймарч на прокси, один фрагмент несёт
 * интеграл вдоль ВСЕГО луча. Аппаратный тест глубины бинарен: он либо срезал
 * объём целиком перед поверхностями (глубина от дальней стенки прокси), либо
 * пропускал целиком вместе с частью ЗА ними (глубина от точки входа) — планета
 * и камни просвечивали сквозь пыль, туманность давала жёсткие вырезы. Честное
 * перекрытие — обрыв марша на глубине сцены, а читать глубину можно только
 * после того, как сцена дорисована.
 *
 * Почему копия глубины. Сцена лежит в inputBuffer, к нему же привязана
 * depth-текстура композера. Рисовать в inputBuffer и сэмплировать его
 * аттачмент — feedback loop, WebGL такой draw отвергает. Поэтому глубина
 * сначала копируется во float-таргет (DepthCopyPass), и объёмы читают копию.
 *
 * Объёмы рисуются В inputBuffer (needsSwap = false) поверх готового кадра, без
 * своей глубины (depthTest/depthWrite OFF у материалов), от дальнего к
 * ближнему по расстоянию до камеры: ближний ложится поверх дальнего (пыль
 * кольца поверх туманности за ним). Атмосфера идёт следом и тонирует их так же,
 * как тонировала бы в основном проходе.
 *
 * Объёмы живут в графе сцены (матрицы считает основной проход) на слое
 * DEPTH_VOLUME_LAYER, который камера обычно не видит; пасс включает слой только
 * на время своего рендера и рендерит каждый объём как корень — обход графа
 * целой сцены второй раз за кадр не нужен. Перед рендером объёму привязывается
 * копия глубины, после — отвязывается: рендер объёма вне пасса (запекание
 * импостора) идёт без обрезки.
 *
 * Объёмы перед активной чёрной дырой пропускаются — их рисует LensFrontPass
 * поверх лензированного кадра.
 */
export class DepthVolumePass extends Pass {
  /** Копия глубины сцены во float-таргет; открыта под тесты */
  public readonly depthCopy: DepthCopyPass

  private readonly sceneCamera: PerspectiveCamera
  private readonly registry: DepthVolumeRegistry
  private readonly front: FrontVolumeFilter | null
  private readonly resolution = new Vector2(1, 1)
  private readonly scaled = new DepthVolumeResolutionRenderer()

  public constructor(camera: PerspectiveCamera, registry: DepthVolumeRegistry, front?: FrontVolumeFilter) {
    super('DepthVolumePass')
    this.sceneCamera = camera
    this.registry = registry
    this.front = front ?? null
    this.needsSwap = false
    this.needsDepthTexture = true
    // BasicDepthPacking → FloatType-таргет, глубина в .r без упаковки
    this.depthCopy = new DepthCopyPass({ depthPacking: BasicDepthPacking })
  }

  public override setDepthTexture(depthTexture: Texture, depthPacking?: DepthPacking): void {
    this.depthCopy.setDepthTexture(depthTexture, depthPacking)
  }

  public override initialize(renderer: WebGLRenderer, alpha: boolean, frameBufferType: number): void {
    this.depthCopy.initialize(renderer, alpha, frameBufferType)
  }

  public override setSize(width: number, height: number): void {
    this.depthCopy.setSize(width, height)
    this.resolution.set(width, height)
  }

  public override render(
    renderer: WebGLRenderer,
    inputBuffer: WebGLRenderTarget | null,
    outputBuffer: WebGLRenderTarget | null,
    deltaTime?: number,
    stencilTest?: boolean
  ): void {
    // Передние объёмы (перед активной линзой) рисует LensFrontPass после линз
    const volumes = orderFarToNear(
      this.registry.volumes().filter((v) => isVisibleInTree(v) && !(this.front?.isFrontVolume(v) ?? false)),
      this.sceneCamera
    )
    if (volumes.length === 0) { this.scaled.prepare(volumes, this.resolution); return }

    this.depthCopy.render(renderer, inputBuffer, outputBuffer, deltaTime, stencilTest)
    drawDepthVolumes(
      renderer,
      this.renderToScreen ? null : inputBuffer,
      this.sceneCamera,
      volumes,
      this.depthCopy.texture,
      this.resolution,
      this.scaled
    )
  }

  public override dispose(): void {
    this.scaled.dispose()
    this.depthCopy.dispose()
    super.dispose()
  }
}

export function isVisibleInTree(object: Object3D): boolean {
  for (let node: Object3D | null = object; node !== null; node = node.parent) {
    if (!node.visible) return false
  }
  return true
}

