// Throwaway diagnostic: freeze the actual reconstruction inputs, then compare
// programs on the same GPU without changing the application or its scene data.
import {
  Color, FloatType, GLSL3, Mesh, NoBlending, OrthographicCamera, PlaneGeometry,
  ShaderMaterial, UniformsUtils, WebGLRenderTarget
} from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { state } from './profile.browser'

const stats = (xs: number[]) => {
  const sorted = xs.slice().sort((a, b) => a - b)
  return { count: xs.length, p50: sorted[Math.ceil(xs.length * .5) - 1], p95: sorted[Math.ceil(xs.length * .95) - 1], max: sorted.at(-1) }
}
const owner = (o: any, id: number) => {
  for (; o; o = o.parent) if (o.model?.getAttribute('id') === id) return true
  return false
}

export async function diagnose(actorId: number, mode = 'split') {
  const c = getInitializedSimulationRuntime()!.container
  const engine: any = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer)
  const volume: any = c.get(Tokens.DepthVolumeRegistry).volumes().find(v => owner(v, actorId))
  if (!volume) throw new Error(`Nebula ${actorId} missing`)
  engine.stop()
  const gl = renderer.getContext() as WebGL2RenderingContext
  const savedTarget = renderer.getRenderTarget(), savedAlpha = renderer.getClearAlpha()
  const savedColor = renderer.getClearColor(new Color()), savedAuto = renderer.autoClear
  const targets: WebGLRenderTarget[] = [], materials: ShaderMaterial[] = []
  let mesh: Mesh, camera: any, uniforms: any, originalSource = '', width = 0, height = 0
  const blitMaterial = new ShaderMaterial({
    glslVersion: GLSL3, uniforms: { map: { value: null } }, depthTest: false, depthWrite: false, blending: NoBlending,
    vertexShader: 'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader: 'precision highp float; uniform sampler2D map; out vec4 fragColor; void main(){fragColor=texelFetch(map,ivec2(gl_FragCoord.xy),0);}'
  })
  const blit = new Mesh(new PlaneGeometry(2, 2), blitMaterial), blitCamera = new OrthographicCamera()
  const draw = renderer.render
  const copy = (source: any) => {
    const target = new WebGLRenderTarget(source.image.width, source.image.height, {
      type: FloatType, depthBuffer: false, minFilter: source.minFilter, magFilter: source.magFilter
    })
    targets.push(target)
    const previous = renderer.getRenderTarget()
    renderer.setRenderTarget(target)
    blitMaterial.uniforms.map.value = source
    draw.call(renderer, blit, blitCamera)
    renderer.setRenderTarget(previous)
    return target.texture
  }
  const read = (target: WebGLRenderTarget) => {
    const pixels = new Float32Array(target.width * target.height * 4)
    renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, pixels)
    if (pixels.some(x => !Number.isFinite(x))) throw new Error('Nonfinite diagnostic image')
    return pixels
  }
  const make = (source: string) => {
    const material = new ShaderMaterial({
      glslVersion: volume.material.glslVersion, vertexShader: volume.material.vertexShader,
      fragmentShader: source, uniforms, defines: { ...volume.material.defines },
      side: volume.material.side, depthTest: false, depthWrite: false, blending: NoBlending
    })
    materials.push(material)
    return material
  }
  try {
    renderer.autoClear = false
    renderer.render = function (object: any, view: any) {
      draw.call(this, object, view)
      if (object !== volume || object.material.uniforms.uLowResolutionEnabled.value < .5 || uniforms) return
      originalSource = object.material.fragmentShader
      uniforms = {}; for (const [name, u] of Object.entries(object.material.uniforms) as any) uniforms[name] = u.value?.isTexture ? { value: u.value } : UniformsUtils.clone({ u }).u
      // Texture uniforms must retain the actual uploaded texture, not an uninitialized clone.
      for (const [name, uniform] of Object.entries(object.material.uniforms) as any) {
        if (uniform.value?.isTexture) uniforms[name].value = uniform.value
      }
      uniforms.uLowResolutionMap.value = copy(object.material.uniforms.uLowResolutionMap.value)
      uniforms.uSceneDepth.value = copy(object.material.uniforms.uSceneDepth.value)
      width = uniforms.uResolution.value.x; height = uniforms.uResolution.value.y
      camera = view.clone()
      mesh = new Mesh(object.geometry, blitMaterial)
      mesh.layers.mask = object.layers.mask
      mesh.matrixAutoUpdate = false
      mesh.matrix.copy(object.matrixWorld)
      mesh.updateMatrixWorld(true)
      mesh.frustumCulled = false
    }
    engine.renderFrame()
    renderer.render = draw
    if (!uniforms) throw new Error('Did not capture reconstruction')
    if (mode === 'weighted' && originalSource.includes('float weightSum =')) {
      throw new Error('This weighted prototype expects the strict baseline helper from 13b3006d; do not rewrite the already-normalized shader')
    }
    console.info('RECONSTRUCT captured', actorId, width, height)
    const snapshot = state()
    const output = new WebGLRenderTarget(width, height, { type: FloatType, depthBuffer: false })
    targets.push(output)
    const mainIndex = originalSource.lastIndexOf('void main()')
    const declarations = originalSource.slice(0, mainIndex)
    const baseline = make(originalSource)
    const loopStart = originalSource.indexOf('    for (int i = 0; i < 4; i++) {')
    const loopEnd = originalSource.indexOf('\n    // A silhouette', loopStart)
    if (loopStart < 0 || loopEnd < 0) throw new Error('Current reconstruction loop absent')
    const unrolledLoop = [0,1,2,3].map(i => `
    if (!(weights[${i}] <= 0.0)) {
      ivec2 p = clamp(base + ivec2(${i%2}, ${Math.floor(i/2)}), ivec2(0), ivec2(uLowResolutionSize) - 1);
      vec2 sourceUV = (vec2(p) + 0.5) / uLowResolutionSize;
      if (nebulaMatchingDepth(depth, texture(uSceneDepth, sourceUV).r)) {
        result += texelFetch(uLowResolutionMap, p, 0) * weights[${i}];
        weightSum += weights[${i}];
      }
    }`).join('\n')
    const unrolled = make(originalSource.slice(0, loopStart) + unrolledLoop + originalSource.slice(loopEnd))
    const mask = make(declarations + `void main(){vec4 result; bool matched=nebulaLowResolution(result); temporalPosition=vec4(0.0); fragColor=matched?vec4(0,1,0,1):vec4(1,0,0,1);}`)
    const reconstruct = make(declarations + `void main(){vec4 result; temporalPosition=vec4(0.0); if(!nebulaLowResolution(result))discard; fragColor=result;}`)
    const fallback = make(originalSource.replace('fragColor = result;\n      return;', 'discard;'))
    if (fallback.fragmentShader === originalSource) throw new Error('Fallback probe replacement failed')
    const render = (variants: ShaderMaterial[]) => {
      renderer.setRenderTarget(output)
      renderer.setClearColor(0, 0)
      renderer.clear(true, false, false)
      for (const material of variants) { mesh.material = material; draw.call(renderer, mesh, camera) }
    }
    const measure = async (variants: ShaderMaterial[]) => {
      const timer = new GpuTimer(gl), samples: number[] = []
      try {
        for (let i = 0; i < 6; i++) { render(variants); await new Promise(r => setTimeout(r, 0)) }
        for (let i = 0; i < 40; i++) {
          timer.measure(() => render(variants))
          await new Promise(r => setTimeout(r, 0))
          samples.push(...timer.poll())
        }
        const deadline = performance.now() + 30000
        while (timer.pendingCount) {
          await new Promise(r => setTimeout(r, 16)); samples.push(...timer.poll())
          if (performance.now() > deadline) throw new Error('GPU query timeout')
        }
        return { summary: stats(samples), samples }
      } finally { timer.dispose() }
    }
    render([mask])
    const maskPixels = read(output), depthPixels = read(targets[1])
    let covered = 0, fallbackPixels = 0, fallbackSky = 0
    for (let i = 0; i < maskPixels.length; i += 4) {
      if (maskPixels[i + 3] > .5) covered++
      if (maskPixels[i] > .5) { fallbackPixels++; if (depthPixels[i] >= 1 - 1e-6) fallbackSky++ }
    }
    if (covered === 0) throw new Error('Diagnostic proxy produced no pixels')
    console.info('RECONSTRUCT mask', actorId, covered, fallbackPixels, fallbackSky)
    render([baseline]); const reference = read(output)
    render([reconstruct, fallback]); const split = read(output)
    let maxError = 0, error = 0, signal = 0, different = 0
    for (let i = 0; i < reference.length; i++) {
      const d = Math.abs(reference[i] - split[i])
      maxError = Math.max(maxError, d); error += d; signal += Math.abs(reference[i]); if (d !== 0) different++
    }
    if (signal === 0) throw new Error('Diagnostic reference image is empty')
    console.info('RECONSTRUCT image', actorId, maxError, error / signal)
    render([unrolled]); const unrolledPixels = read(output); let unrolledDifferentBits = 0; const rb = new Uint32Array(reference.buffer), ub = new Uint32Array(unrolledPixels.buffer); for(let i=0;i<rb.length;i++) if(rb[i] !== ub[i]) unrolledDifferentBits++;
    let experiment: any = { unrolledDifferentBits }
    let measurements: any
    if (mode === 'weighted') {
      const start = originalSource.indexOf('  bool nebulaLowResolution(')
      const end = originalSource.indexOf('\n  }', start) + 4
      const old = originalSource.slice(start, end)
      const replacement = old.replace('result = vec4(0.0);', 'result = vec4(0.0); float weightSum = 0.0;')
        .replace('if (!nebulaMatchingDepth(depth, texture(uSceneDepth, sourceUV).r)) return false;', 'if (!nebulaMatchingDepth(depth, texture(uSceneDepth, sourceUV).r)) continue;')
        .replace('result += texelFetch(uLowResolutionMap, p, 0) * weights[i];', 'result += texelFetch(uLowResolutionMap, p, 0) * weights[i]; weightSum += weights[i];')
        .replace('return true;', 'if (weightSum <= 0.0) return false; result /= weightSum; return true;')
      if (start < 0 || !replacement.includes('continue;') || !replacement.includes('result /= weightSum')) throw new Error('Weighted replacement failed')
      const weightedSource = originalSource.slice(0, start) + replacement + originalSource.slice(end)
      const weighted = make(weightedSource)
      const weightedMask = make(weightedSource.slice(0, weightedSource.lastIndexOf('void main()')) + `void main(){vec4 result; bool matched=nebulaLowResolution(result); temporalPosition=vec4(0.0); fragColor=matched?vec4(0,1,0,1):vec4(1,0,0,1);}`)
      render([weightedMask]); const newMask = read(output)
      let weightedFallback = 0, weightedSky = 0
      for (let i = 0; i < newMask.length; i += 4) if (newMask[i] > .5) { weightedFallback++; if (depthPixels[i] >= 1 - 1e-6) weightedSky++ }
      render([weighted]); const candidate = read(output)
      uniforms.uLowResolutionEnabled.value = 0
      render([baseline]); const native = read(output)
      uniforms.uLowResolutionEnabled.value = 1
      const compare = (a: Float32Array, b: Float32Array, edgeOnly = false) => {
        let maxError = 0, error = 0, signal = 0, components = 0
        for (let i = 0; i < a.length; i++) {
          if (edgeOnly && maskPixels[i - i % 4] < .5) continue
          const d = Math.abs(a[i] - b[i]); maxError = Math.max(maxError, d); error += d; signal += Math.abs(a[i]); components++
        }
        return { maxError, relativeError: error / Math.max(signal, 1e-8), meanAbsoluteError: error / components }
      }
      experiment = { weightedFallback, weightedSky, fallbackFraction: weightedFallback / covered,
        baselineVsNative: compare(native, reference), weightedVsNative: compare(native, candidate),
        changedEdgesVsNative: compare(native, candidate, true), weightedVsBaseline: compare(reference, candidate) }
      console.info('RECONSTRUCT weighted', actorId, JSON.stringify(experiment))
      measurements = { baseline: await measure([baseline]), weighted: await measure([weighted]), baselineRepeat: await measure([baseline]) }
    } else {
      measurements = { baseline: await measure([baseline]), reconstructOnly: await measure([reconstruct]),
        fallbackOnly: await measure([fallback]), split: await measure([reconstruct, fallback]), unrolled: await measure([unrolled]), baselineRepeat: await measure([baseline]) }
    }
    const glError = gl.getError()
    if (glError !== gl.NO_ERROR) throw new Error(`GPU error ${glError}`)
    return { actorId, width, height, snapshot, covered, fallbackPixels, fallbackSky,
      fallbackFraction: fallbackPixels / covered, image: { maxError, relativeError: error / signal, different }, experiment, measurements }
  } finally {
    renderer.render = draw
    for (const material of materials) material.dispose()
    for (const target of targets) target.dispose()
    blit.geometry.dispose(); blitMaterial.dispose()
    renderer.setRenderTarget(savedTarget)
    renderer.setClearColor(savedColor, savedAlpha); renderer.autoClear = savedAuto
    engine.start()
  }
}

