    console.info('RECONSTRUCT stencil', actorId, stencilDifferentBits);
    let experiment: any = { unrolledDifferentBits, stencilDifferentBits }
    let measurements: any
    if (mode === 'weighted') {
      const start = originalSource.indexOf('  bool nebulaLowResolution(')
      const end = originalSource.indexOf('\n  }', start) + 4
      const old = originalSource.slice(start, end)
      const replacement = old.replace('result = vec4(0.0);', 'result = vec4(0.0); float weightSum = 0.0;')
        .replace('if (!nebulaMatchingDepth(depth, texture(uSceneDepth, sourceUV).r)) return false;', 'if (!nebulaMatchingDepth(depth, texture(uSceneDepth, sourceUV).r)) continue;')
        .replace('result += texelFetch(uLowResolutionMap, p, 0) * weights[i];', 'result += texelFetch(uLowResolutionMap, p, 0) * weights[i]; weightSum += weights[i];')
        .replace('return true;', 'if (weightSum <= 0.0) return false; result /= weightSum; return true;')
