    } else {
      measurements = { baseline: await measure([baseline]), reconstructOnly: await measure([reconstruct]),
        fallbackOnly: await measure([fallback]), stencil: await measure([stencilReconstruct, stencilFallback]), baselineRepeat: await measure([baseline]) }
    }
    const glError = gl.getError()
    if (glError !== gl.NO_ERROR) throw new Error(`GPU error ${glError}`)
    return { actorId, width, height, snapshot, covered, fallbackPixels, fallbackSky,
      fallbackFraction: fallbackPixels / covered, image: { maxError, relativeError: error / signal, different }, experiment, measurements }
  } finally {
    renderer.render = draw
    for (const material of materials) material.dispose()
    for (const target of targets) target.dispose()
    blit.geometry.dispose(); blitMaterial.dispose()
    renderer.setRenderTarget(savedTarget)
    renderer.setClearColor(savedColor, savedAlpha); renderer.autoClear = savedAuto
    engine.start()
  }
}

