import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { writeFile } from 'node:fs/promises'
Object.assign(process.env, { VITE_FS_DRIVER: 's3', VITE_S3_URL: 'https://storage.yandexcloud.net', VITE_FILE_BUCKET: 'textures', VITE_SHOW_STATS_PANEL: 'false', VITE_SKY_SOURCE: 'gaia' })
const output = 'benchmark-results/heavy-scenes/volume-work-production-2026-10-23.json'
const report = { baselineCommit: '422cbb813465b988f13bf1204b9b6199275a9def', startedAt: new Date().toISOString(), rows: [], errors: [], warnings: [], assetFailures: [], outcome: 'failed' }
let server, browser
try {
  server = await createServer({ server: { host: '127.0.0.1', port: 8094, strictPort: true, hmr: false } }); await server.listen()
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()); if (m.text().startsWith('VOLUME_CONFIRM')) console.log(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`) })
  page.on('requestfailed', r => { if (!/ERR_ABORTED/.test(r.failure()?.errorText ?? '')) report.assetFailures.push(`${r.failure()?.errorText} ${r.url()}`) })
  await page.goto('http://127.0.0.1:8094/'); await page.getByRole('button', { name: /^Run / }).first().waitFor()
  for (const [id, actor, nebula] of [[13, 135, 136], [12, 127, 118]]) {
    console.log('Starting', id)
    await page.evaluate(async id => Promise.race([(await import('/tests/browser/scenarioSoak.browser.ts')).selectScenario(id), new Promise((_, reject) => setTimeout(() => reject(new Error('Startup timeout')), 180000))]), id)
    const view = await page.evaluate(async actor => (await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(actor, 'belt'), actor)
    await page.waitForTimeout(5000)
    const row = { id, view, frozen: [] }; report.rows.push(row)
    for (const translated of [false, true]) {
      const result = await page.evaluate(async ({ nebula, translated }) => (await import('/benchmark-results/heavy-scenes/volume-work-production-2026-10-23.browser.ts')).confirm(nebula, translated), { nebula, translated })
      if (/SwiftShader|llvmpipe|software/i.test(result.snapshot.renderer)) throw new Error('Software renderer')
      row.frozen.push(result); await writeFile(output, JSON.stringify(report, null, 2))
    }
    row.moving = await page.evaluate(async () => (await import('/benchmark-results/heavy-scenes/volume-work-production-2026-10-23.browser.ts')).moving())
    console.log('MOTION', id, JSON.stringify(row.moving.summary))
    await page.screenshot({ path: `benchmark-results/heavy-scenes/volume-work-production-2026-10-23-${id}.png` })
    await writeFile(output, JSON.stringify(report, null, 2))
    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.warnings.length || report.assetFailures.length) throw new Error('Browser, shader or asset issue')
  }
  report.outcome = 'completed'
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await writeFile(output, JSON.stringify(report, null, 2)); await browser?.close(); await server?.close() }

