}
export async function moving() {
  const c = getInitializedSimulationRuntime()!.container, engine = c.get(Tokens.Engine), camera = c.get(Tokens.Camera)
  const position = camera.position.clone(), orientation = camera.quaternion.clone(), originalFrame = engine.renderFrame
  const direction = new Vector3(1, 0, 0).applyQuaternion(orientation)
  let frame = 0
  engine.renderFrame = function () {
    if (frame >= 64) return originalFrame.call(this)
    const progress = frame++ / 63
    camera.position.copy(position).addScaledVector(direction, progress * 2)
    camera.quaternion.copy(orientation); camera.rotateY(progress * Math.PI * 2); camera.updateMatrixWorld(true)
    return originalFrame.call(this)
  }
  try {
    const result = await profile(64, 'passes', false)
    if (frame !== 64) throw new Error('Incomplete motion window')
    return { ...result, caveat: '64 real frames,4000km translation and360degree turn. Actual pass GPU/CPU measured; no paired motion baseline and no whole-frame speedup claim.' }
  } finally {
    engine.renderFrame = originalFrame; camera.position.copy(position); camera.quaternion.copy(orientation)
  }
}

